fn find_smallest(s: &Vec<u32>) -> Option<u32> {
    if s.is_empty() {
        return None; // Return None if the vector is empty
    }

    let mut smallest = s[0]; // Start with the first element as the smallest
    for &value in s.iter() {
        if value < smallest {
            smallest = value; // Update smallest if a smaller value is found
        }
    }

    Some(smallest) // Return the smallest value wrapped in Some
}